WITH unpacked AS (SELECT id, coupon_codes, items, attributes, TRY_CAST(attributes['weight_kg'] AS DOUBLE) AS weight_kg, ARRAY_MAX(TRANSFORM(items, i -> i.price)) AS max_item_price, SIZE(items) AS num_items FROM carts) SELECT id, weight_kg, max_item_price, SUM(num_items) OVER (ORDER BY num_items, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_sum_num_items, MIN(num_items) OVER (ORDER BY num_items, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_min_num_items, MAX(num_items) OVER (ORDER BY num_items, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_max_num_items FROM unpacked WHERE num_items >= 2
